import React, { useState } from 'react';

const HostelForm = ({ onAddHostel, submitting }) => {
  // Form input state (NO ID field - ID is strictly generated by the backend)
  const [formData, setFormData] = useState({
    hostelName: '',
    location: '',
    roomCount: '',
    wardenName: '',
  });

  // Field-specific validation error state
  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});

  // Validate a single field or all fields
  const validate = (dataToValidate = formData) => {
    const errs = {};

    // 1. hostelName validation: required & non-empty
    if (!dataToValidate.hostelName || dataToValidate.hostelName.trim() === '') {
      errs.hostelName = 'Hostel name is required.';
    } else if (dataToValidate.hostelName.trim().length < 2) {
      errs.hostelName = 'Hostel name must be at least 2 characters.';
    }

    // 2. location validation: required & non-empty
    if (!dataToValidate.location || dataToValidate.location.trim() === '') {
      errs.location = 'Location is required.';
    }

    // 3. roomCount validation: required & strictly positive integer (> 0)
    if (
      dataToValidate.roomCount === '' ||
      dataToValidate.roomCount === null ||
      dataToValidate.roomCount === undefined
    ) {
      errs.roomCount = 'Room count is required.';
    } else {
      const parsed = Number(dataToValidate.roomCount);
      if (isNaN(parsed)) {
        errs.roomCount = 'Room count must be a valid number.';
      } else if (!Number.isInteger(parsed)) {
        errs.roomCount = 'Room count must be a whole integer (no decimals).';
      } else if (parsed <= 0) {
        errs.roomCount = 'Room count must be greater than zero.';
      }
    }

    // 4. wardenName validation: required & non-empty
    if (!dataToValidate.wardenName || dataToValidate.wardenName.trim() === '') {
      errs.wardenName = 'Warden name is required.';
    }

    return errs;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    const updatedForm = { ...formData, [name]: value };
    setFormData(updatedForm);

    // Validate actively if already touched
    if (touched[name]) {
      const validationErrors = validate(updatedForm);
      setErrors(validationErrors);
    }
  };

  const handleBlur = (e) => {
    const { name } = e.target;
    setTouched({ ...touched, [name]: true });
    const validationErrors = validate();
    setErrors(validationErrors);
  };

  const handleReset = () => {
    setFormData({
      hostelName: '',
      location: '',
      roomCount: '',
      wardenName: '',
    });
    setErrors({});
    setTouched({});
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Mark all fields touched
    setTouched({
      hostelName: true,
      location: true,
      roomCount: true,
      wardenName: true,
    });

    const validationErrors = validate();
    setErrors(validationErrors);

    // If any validation error exists, abort submission
    if (Object.keys(validationErrors).length > 0) {
      return;
    }

    // Submit payload to parent handler (App.jsx -> hostelService.createHostel)
    const success = await onAddHostel({
      hostelName: formData.hostelName.trim(),
      location: formData.location.trim(),
      roomCount: parseInt(formData.roomCount, 10),
      wardenName: formData.wardenName.trim(),
    });

    // Reset form after successful submission
    if (success) {
      handleReset();
    }
  };

  return (
    <div className="card custom-card">
      <div className="card-header card-header-custom d-flex align-items-center justify-content-between">
        <div className="d-flex align-items-center gap-2">
          <i className="bi bi-plus-circle-fill text-primary fs-5"></i>
          <span className="fs-5">Add New Hostel</span>
        </div>
        <span className="badge bg-light text-muted border">No ID Required</span>
      </div>

      <div className="card-body p-4">
        <form onSubmit={handleSubmit} noValidate>
          {/* Hostel Name Input */}
          <div className="mb-3">
            <label htmlFor="hostelName" className="form-label fw-semibold">
              Hostel Name <span className="text-danger">*</span>
            </label>
            <div className="input-group">
              <span className="input-group-text bg-light text-muted">
                <i className="bi bi-building"></i>
              </span>
              <input
                type="text"
                className={`form-control ${touched.hostelName && errors.hostelName ? 'is-invalid' : ''} ${touched.hostelName && !errors.hostelName ? 'is-valid' : ''}`}
                id="hostelName"
                name="hostelName"
                placeholder="e.g. Gargi Bhavan / Kaveri Hostel"
                value={formData.hostelName}
                onChange={handleChange}
                onBlur={handleBlur}
                disabled={submitting}
              />
              {touched.hostelName && errors.hostelName && (
                <div className="invalid-feedback">{errors.hostelName}</div>
              )}
            </div>
          </div>

          {/* Location Input */}
          <div className="mb-3">
            <label htmlFor="location" className="form-label fw-semibold">
              Location / Block <span className="text-danger">*</span>
            </label>
            <div className="input-group">
              <span className="input-group-text bg-light text-muted">
                <i className="bi bi-geo-alt"></i>
              </span>
              <input
                type="text"
                className={`form-control ${touched.location && errors.location ? 'is-invalid' : ''} ${touched.location && !errors.location ? 'is-valid' : ''}`}
                id="location"
                name="location"
                placeholder="e.g. North Campus, Block C"
                value={formData.location}
                onChange={handleChange}
                onBlur={handleBlur}
                disabled={submitting}
              />
              {touched.location && errors.location && (
                <div className="invalid-feedback">{errors.location}</div>
              )}
            </div>
          </div>

          {/* Room Count Input */}
          <div className="mb-3">
            <label htmlFor="roomCount" className="form-label fw-semibold">
              Total Rooms <span className="text-danger">*</span>
            </label>
            <div className="input-group">
              <span className="input-group-text bg-light text-muted">
                <i className="bi bi-door-closed"></i>
              </span>
              <input
                type="number"
                min="1"
                step="1"
                className={`form-control ${touched.roomCount && errors.roomCount ? 'is-invalid' : ''} ${touched.roomCount && !errors.roomCount ? 'is-valid' : ''}`}
                id="roomCount"
                name="roomCount"
                placeholder="e.g. 150 (must be > 0)"
                value={formData.roomCount}
                onChange={handleChange}
                onBlur={handleBlur}
                disabled={submitting}
              />
              {touched.roomCount && errors.roomCount && (
                <div className="invalid-feedback">{errors.roomCount}</div>
              )}
            </div>
            <div className="form-text small text-muted">
              Must be a positive integer greater than zero.
            </div>
          </div>

          {/* Warden Name Input */}
          <div className="mb-4">
            <label htmlFor="wardenName" className="form-label fw-semibold">
              Warden Name <span className="text-danger">*</span>
            </label>
            <div className="input-group">
              <span className="input-group-text bg-light text-muted">
                <i className="bi bi-person"></i>
              </span>
              <input
                type="text"
                className={`form-control ${touched.wardenName && errors.wardenName ? 'is-invalid' : ''} ${touched.wardenName && !errors.wardenName ? 'is-valid' : ''}`}
                id="wardenName"
                name="wardenName"
                placeholder="e.g. Dr. K. V. Sharma"
                value={formData.wardenName}
                onChange={handleChange}
                onBlur={handleBlur}
                disabled={submitting}
              />
              {touched.wardenName && errors.wardenName && (
                <div className="invalid-feedback">{errors.wardenName}</div>
              )}
            </div>
          </div>

          {/* Buttons: Submit & Reset */}
          <div className="d-flex gap-2">
            <button
              type="submit"
              className="btn btn-primary flex-grow-1 d-flex align-items-center justify-content-center gap-2 py-2"
              disabled={submitting}
            >
              {submitting ? (
                <>
                  <span className="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>
                  <span>Saving Hostel...</span>
                </>
              ) : (
                <>
                  <i className="bi bi-check-circle-fill"></i>
                  <span>Add Hostel</span>
                </>
              )}
            </button>

            <button
              type="button"
              className="btn btn-outline-secondary px-3"
              onClick={handleReset}
              disabled={submitting}
              title="Reset Form"
            >
              <i className="bi bi-arrow-counterclockwise"></i>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default HostelForm;
